steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issue(identifier: \"MOB-42\") { id identifier title subIssues { id identifier title estimate dueDate priority } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 10, filter: {identifier: {eq: \"MOB-42\"}}) { nodes { id identifier title } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(search: \"MOB-42\", first: 10) { nodes { id identifier title } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50) { nodes { id identifier title } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50, filter: {parentId: {eq: \"i-mob-42\"}}) { nodes { id identifier title estimate dueDate priority } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50, filter: {parent: {eq: \"i-mob-42\"}}) { nodes { id identifier title estimate dueDate priority } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50, filter: {parent: {id: {eq: \"i-mob-42\"}}}) { nodes { id identifier title estimate dueDate priority } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50) { nodes { id identifier title estimate dueDate priority parentId } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 50) { nodes { id identifier title estimate dueDate priority parent { id } } } }"
}'
